using Jindan.Contracts;
namespace Jindan.Modules.Files;

public sealed partial class FileDocument
{
    readonly Stack<string> backFolders = new(), forwardFolders = new();
    readonly ListView tiles = new() { Dock = DockStyle.Fill, View = System.Windows.Forms.View.Tile, TileSize = new Size(260, 72), MultiSelect = true, HideSelection = false, Name = "FileTiles", Visible = false };
    bool updatingTiles;
    sealed record FolderMove(string ContextId, string? ProjectId, string[] Ids);
    void InitializeGestures()
    {
        AddAction("뒤로", () => NavigateHistoryAsync(false)); AddAction("앞으로", () => NavigateHistoryAsync(true));
        AddAction("자료 이름 변경", RenameFileDialogAsync); AddAction("목록/타일", () => { SetTileView(!tiles.Visible); return Task.CompletedTask; });
        tiles.Columns.Add("자료명"); tiles.Columns.Add("분류"); tiles.Columns.Add("크기"); Controls.Add(tiles); tiles.BringToFront();
        Grid.RowsAdded += (_, _) => SyncTiles(); Grid.RowsRemoved += (_, _) => SyncTiles();
        tiles.SelectedIndexChanged += (_, _) => { if (updatingTiles) return; Grid.ClearSelection(); foreach (ListViewItem item in tiles.SelectedItems) foreach (DataGridViewRow row in Grid.Rows) if (row.Tag is WorkRecord record && record.Id == ((WorkRecord)item.Tag!).Id) { row.Selected = true; Grid.CurrentCell = row.Cells[0]; } };
        Grid.KeyDown += async (_, e) => { if (e.KeyCode == Keys.F2) { e.SuppressKeyPress = true; await RunAsync(RenameFileDialogAsync); } };
        tiles.KeyDown += async (_, e) => { if (e.KeyCode == Keys.F2) { e.SuppressKeyPress = true; await RunAsync(RenameFileDialogAsync); } };
        folders.KeyDown += async (_, e) => { if (e.KeyCode == Keys.F2) { e.SuppressKeyPress = true; await RunAsync(RenameFolderDialogAsync); } };
        Grid.MouseDown += (_, e) => { var hit = Grid.HitTest(e.X, e.Y); if (e.Button == MouseButtons.Left && hit.RowIndex >= 0 && Grid.Rows[hit.RowIndex].Selected) dragStart = e.Location; else dragStart = null; };
        Grid.MouseMove += (_, e) => { if (e.Button != MouseButtons.Left || dragStart is not Point start || Math.Abs(e.X - start.X) + Math.Abs(e.Y - start.Y) < 12) return; dragStart = null; var ids = Grid.SelectedRows.Cast<DataGridViewRow>().Select(r => r.Tag).OfType<WorkRecord>().Select(r => r.Id).ToArray(); if (ids.Length > 0 && !IsDirty) Grid.DoDragDrop(new FolderMove(Context.ContextId, Context.ProjectId, ids), DragDropEffects.Move); };
        folders.AllowDrop = true; folders.DragOver += (_, e) => { e.Effect = MovePayload(e.Data) is not null ? DragDropEffects.Move : DragDropEffects.None; };
        folders.DragDrop += async (_, e) => { var payload = MovePayload(e.Data); var node = folders.GetNodeAt(folders.PointToClient(new Point(e.X, e.Y))); if (payload is null || node?.Tag is not string target) return; await RunAsync(() => MoveSelectionToFolderAsync(payload.Ids, target, folderLifetime.Token)); };
        foreach (var surface in new Control[] { Grid, tiles }) { surface.AllowDrop = true; surface.DragEnter += (_, e) => { e.Effect = !IsDirty && Context.ProjectId is not null && e.Data?.GetDataPresent(DataFormats.FileDrop) == true ? DragDropEffects.Copy : DragDropEffects.None; }; surface.DragDrop += async (_, e) => { if (e.Data?.GetData(DataFormats.FileDrop) is not string[] paths) return; await RunAsync(() => ImportDroppedPathsAsync(paths, folderLifetime.Token)); }; }
    }
    Point? dragStart;
    FolderMove? MovePayload(IDataObject? data) => !IsDirty && data?.GetData(typeof(FolderMove)) is FolderMove p && p.ContextId == Context.ContextId && p.ProjectId == Context.ProjectId ? p : null;
    public void SetTileView(bool enabled) { SyncTiles(); tiles.Visible = enabled; Grid.Visible = !enabled; if (enabled) { tiles.BringToFront(); } }
    void SyncTiles() { if (IsDisposed || Disposing || tiles.IsDisposed || updatingTiles) return; updatingTiles = true; tiles.BeginUpdate(); try { var selected = tiles.SelectedItems.Cast<ListViewItem>().Select(i => ((WorkRecord)i.Tag!).Id).ToHashSet(); tiles.Items.Clear(); foreach (DataGridViewRow row in Grid.Rows) if (row.Tag is WorkRecord record) { var item = new ListViewItem(record.Fields.GetValueOrDefault("title", "")) { Tag = record, Selected = selected.Contains(record.Id) }; item.SubItems.Add(record.Fields.GetValueOrDefault("category", "")); item.SubItems.Add(record.Fields.GetValueOrDefault("size", "") + " B"); tiles.Items.Add(item); } } finally { tiles.EndUpdate(); updatingTiles = false; } }
    public async Task NavigateFolderAsync(string target, CancellationToken ct = default) { if (IsDirty) throw new InvalidOperationException("변경 내용을 먼저 저장하세요."); if (target == currentFolder) return; if (target.Length > 0 && !(await Services.Data.ListAsync(Services.Actor, new("file-folders", Context.ProjectId), ct)).Any(r => r.Id == target)) throw new InvalidOperationException("현재 프로젝트의 폴더를 선택하세요."); backFolders.Push(currentFolder); forwardFolders.Clear(); currentFolder = target; NewRecord(); await RefreshAsync(); }
    public async Task NavigateHistoryAsync(bool forward) { if (IsDirty) throw new InvalidOperationException("변경 내용을 먼저 저장하세요."); var from = forward ? forwardFolders : backFolders; var to = forward ? backFolders : forwardFolders; var available = (await Services.Data.ListAsync(Services.Actor, new("file-folders", Context.ProjectId), folderLifetime.Token)).Select(r => r.Id).Append("").ToHashSet(); while (from.TryPop(out var target)) { if (!available.Contains(target)) continue; to.Push(currentFolder); currentFolder = target; NewRecord(); await RefreshAsync(); return; } }
    public async Task ImportDroppedPathsAsync(IEnumerable<string> paths, CancellationToken ct = default) { var files = paths.ToArray(); if (files.Length is < 1 or > 500 || files.Any(p => !Path.IsPathFullyQualified(p) || !File.Exists(p) || Directory.Exists(p))) throw new InvalidOperationException("1~500개 로컬 파일을 선택하세요. 폴더는 재귀 가져오기하지 않습니다."); foreach (var file in files) { ct.ThrowIfCancellationRequested(); await ImportPathAsync(file, ct); } await RefreshAsync(); }
    public async Task MoveSelectionToFolderAsync(IEnumerable<string> ids, string target, CancellationToken ct = default) { foreach (var id in ids.Distinct()) { ct.ThrowIfCancellationRequested(); await MoveToFolderAsync(id, target, ct); } NewRecord(); await RefreshAsync(); }
    public async Task RenameFileAsync(string id, string title, CancellationToken ct = default) { if (IsDirty) throw new InvalidOperationException("변경 내용을 먼저 저장하세요."); var row = (await Services.Data.ListAsync(Services.Actor, new("files", Context.ProjectId), ct)).Single(r => r.Id == id); var fields = new Dictionary<string, string>(row.Fields) { ["title"] = title }; await Services.Data.SaveAsync(Services.Actor, new(row.Id, row.Kind, row.ProjectId, row.Revision, fields), ct); NewRecord(); await RefreshAsync(); }
    async Task RenameFileDialogAsync() { if (Selected is null) return; using var form = new Form() { Text = "자료 이름 변경 · 원본 보존", Width = 400, Height = 160, StartPosition = FormStartPosition.CenterParent }; var text = new TextBox() { Dock = DockStyle.Top, Text = Selected.Fields["title"] }; var save = new Button() { Dock = DockStyle.Bottom, Text = "변경", DialogResult = DialogResult.OK }; form.Controls.Add(text); form.Controls.Add(save); form.AcceptButton = save; if (form.ShowDialog(this) == DialogResult.OK) await RenameFileAsync(Selected.Id, text.Text); }
}
